import { FC, useId } from "react";

import { IIconProps } from "@/types/icons";

export const OfflinePageBackgroundPhoto: FC<IIconProps> = ({
  width = 558,
  height = 738,
}) => {
  const uniqueId = useId();
  const patternId = `${uniqueId}-pattern`;
  const imageId = `${uniqueId}-image`;

  return (
    <svg
      width={width}
      height={height}
      viewBox="0 0 558 738"
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      xmlnsXlink="http://www.w3.org/1999/xlink"
    >
      <rect
        width="557.273"
        height="737.11"
        transform="matrix(-1 0 0 1 557.272 0)"
        fill={`url(#${patternId})`}
      />
      <defs>
        <pattern
          id={patternId}
          patternContentUnits="objectBoundingBox"
          width="1"
          height="1"
        >
          <use
            xlinkHref={`#${imageId}`}
            transform="matrix(0.000504796 0 0 0.000381637 0 -0.133844)"
          />
        </pattern>
        <image
          id={imageId}
          width="1981"
          height="2971"
          preserveAspectRatio="none"
          xlinkHref="data:image/png;base64,"
        />
      </defs>
    </svg>
  );
};

export default OfflinePageBackgroundPhoto;
